Tool response:
Tool: get_lowest_performing_criteria
Description: Identify the three rubric criteria with the lowest average scores across all 
submissions for a given assignment.
Parameters:
    {
      "type": "object",
      "properties": {
        "assignment_id": {
          "type": "integer",
          "title": "Assignment Id",
          "description": ""
        }
      },
      "required": [
        "assignment_id"
      ]
    }

Tool response:
Tool: get_assignment_rubric_criteria_performance
Description: Retrieve the average scores for each rubric criterion across all submissions 
for a specific assignment, ordered by average score ascending.
Parameters:
    {
      "type": "object",
      "properties": {
        "assignment_id": {
          "type": "integer",
          "title": "Assignment Id",
          "description": ""
        }
      },
      "required": [
        "assignment_id"
      ]
    }

Tool response:
Tool: get_criterion_detailed_breakdown
Description: View detailed score distribution and feedback for a specific rubric criterion 
across all submissions for an assignment.
Parameters:
    {
      "type": "object",
      "properties": {
        "assignment_id": {
          "type": "integer",
          "title": "Assignment Id",
          "description": ""
        },
        "criterion_id": {
          "type": "integer",
          "title": "Criterion Id",
          "description": ""
        }
      },
      "required": [
        "assignment_id",
        "criterion_id"
      ]
    }
